<?php
require_once __DIR__.'/../includes/auth.php'; $u=require_role('provider'); $uid=(int)$u['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try{ $headline=clean_text($_POST['headline']??'',180,true,'Headline');$about=clean_text($_POST['about']??'',10000,true,'About');$exp=(int)($_POST['experience_years']??0);if($exp<0||$exp>80)throw new RuntimeException('Experience years are outside the allowed range.');$area=clean_text($_POST['service_area']??'',255,true,'Service area');$pmin=nullable_money($_POST['price_min']??null,'Minimum price');$pmax=nullable_money($_POST['price_max']??null,'Maximum price');$avail=(string)($_POST['availability_status']??'available');if(!in_array($avail,['available','busy','unavailable'],true))throw new RuntimeException('Availability value is invalid.');$hours=clean_text($_POST['working_hours']??'',255,false,'Working hours');$city=clean_text($_POST['city']??'',100,true,'City');$state=clean_text($_POST['state']??'',100,true,'State');$localArea=clean_text($_POST['area']??'',150,false,'Area');$pin=clean_text($_POST['pincode']??'',12,false,'Pincode');if(!valid_pincode_or_empty($pin))throw new RuntimeException('Pincode is invalid.');if($pmin!==null&&$pmax!==null&&$pmax<$pmin)throw new RuntimeException('Maximum price cannot be lower than minimum price.'); $oldQ=db()->prepare('SELECT profile_image FROM users WHERE id=?');$oldQ->execute([$uid]);$oldImage=(string)($oldQ->fetchColumn()?:''); $img=upload_image($_FILES['profile_image']??[],'profiles'); db()->beginTransaction(); $s=db()->prepare("UPDATE users SET city=?,state=?,area=?,pincode=?".($img?',profile_image=?':'')." WHERE id=?"); $args=[$city,$state,$localArea,$pin]; if($img)$args[]=$img;$args[]=$uid;$s->execute($args); $s=db()->prepare("UPDATE provider_profiles SET headline=?,about=?,experience_years=?,service_area=?,price_min=?,price_max=?,availability_status=?,working_hours=? WHERE user_id=?");$s->execute([$headline,$about,$exp,$area,$pmin,$pmax,$avail,$hours,$uid]);db()->commit();if($img&&$oldImage&&$oldImage!==$img)delete_managed_upload($oldImage);flash('success','Provider profile updated successfully.');redirect('provider/profile.php'); }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if(isset($img)&&$img)delete_managed_upload($img);$error=$e instanceof RuntimeException?$e->getMessage():'Could not update profile.';} }
$s=db()->prepare("SELECT u.*,p.* FROM users u JOIN provider_profiles p ON p.user_id=u.id WHERE u.id=?");$s->execute([$uid]);$p=$s->fetch();$pageTitle='My Provider Profile — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-5"><div class="row justify-content-center"><div class="col-lg-9"><div class="d-flex justify-content-between mb-4"><div><h1 class="fw-bold">Provider profile</h1><p class="text-muted">Build the profile customers will discover in search.</p></div><a class="btn btn-outline-primary align-self-start" href="<?=e(base_url('provider.php?id='.$uid))?>">Public View</a></div><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="soft-card p-4"><?=csrf_field()?><div class="row g-3"><div class="col-md-8"><label class="form-label">Professional headline *</label><input class="form-control" name="headline" required value="<?=e($p['headline'])?>" placeholder="Electrician & home wiring specialist"></div><div class="col-md-4"><label class="form-label">Experience (years)</label><input type="number" min="0" class="form-control" name="experience_years" value="<?=e((string)$p['experience_years'])?>"></div><div class="col-12"><label class="form-label">About *</label><textarea class="form-control" rows="4" name="about" required><?=e($p['about'])?></textarea></div><div class="col-md-6"><label class="form-label">Service area *</label><input class="form-control" name="service_area" required value="<?=e($p['service_area'])?>"></div><div class="col-md-6"><label class="form-label">Working hours</label><input class="form-control" name="working_hours" value="<?=e($p['working_hours'])?>" placeholder="Mon-Sat, 9 AM-7 PM"></div><div class="col-md-4"><label class="form-label">Availability</label><select class="form-select" name="availability_status"><?php foreach(['available'=>'Available','busy'=>'Busy','unavailable'=>'Unavailable'] as $k=>$v):?><option value="<?=$k?>" <?=$p['availability_status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Price from ₹</label><input type="number" min="0" step="0.01" class="form-control" name="price_min" value="<?=e((string)$p['price_min'])?>"></div><div class="col-md-4"><label class="form-label">Price to ₹</label><input type="number" min="0" step="0.01" class="form-control" name="price_max" value="<?=e((string)$p['price_max'])?>"></div><div class="col-md-4"><label class="form-label">City *</label><input class="form-control" name="city" required value="<?=e($p['city'])?>"></div><div class="col-md-4"><label class="form-label">State *</label><input class="form-control" name="state" required value="<?=e($p['state'])?>"></div><div class="col-md-2"><label class="form-label">Area</label><input class="form-control" name="area" value="<?=e($p['area'])?>"></div><div class="col-md-2"><label class="form-label">Pincode</label><input class="form-control" name="pincode" value="<?=e($p['pincode'])?>"></div><div class="col-12"><label class="form-label">Profile image</label><input type="file" class="form-control" name="profile_image" accept="image/jpeg,image/png,image/webp"><small class="text-muted">JPG, PNG or WEBP, max 3 MB.</small></div><div class="col-12"><button class="btn btn-primary">Save Profile</button></div></div></form></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
